// CSD_RATIONALE_BEGIN
// The previous attempt used GenerateWithManagedSpan, which closes the constrained
// span immediately when parser.IsCompletePrefix is true. For gsm_symbolic, a
// single variable name like "n0" is a complete Python expression, so every span
// closed after exactly 1 token. Correct answers are compound algebraic formulas
// like "n0 * (r+1)**d".
//
// This strategy fixes the problem with three targeted interventions:
// 1. AppendTaskGuidance instructs the model to produce complete arithmetic
//    expressions in terms of ALL variables, never a single bare variable.
// 2. A custom loop keeps the span open: for the first 5 constrained tokens,
//    SafePenalizedConstrainedStep penalizes EOS to prevent premature exit;
//    beyond 5 tokens, AdaptiveConstrainedStep is used. The loop never closes
//    the span based on parser completeness – the model generates until EOS or
//    budget exhaustion, allowing the full algebraic expression to emerge.
// 3. CloseSpanWithinBudget closes the open span at the last complete prefix
//    using remaining budget after the main loop ends.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch: When RenderedEndsWith detects "<<", we set
//   currentConstrainedOut := [] and insideConstrainedOut := true. The
//   precondition parser.IsValidPrefix([]) holds by the method requires, so
//   the implication is satisfied. When "<<" is not detected, insideConstrainedOut
//   remains false, making the implication vacuously true.
//
//   Inside-span branch (|currentConstrainedOut| < 5): SafePenalizedConstrainedStep
//   returns eosToken or a token t with parser.IsValidPrefix(currentConstrainedOut + [t]).
//   AppendConstrainedToken extends currentConstrainedOut to that valid prefix. The
//   implication holds after the extension.
//
//   Inside-span branch (|currentConstrainedOut| >= 5): AdaptiveConstrainedStep
//   has the same parser-validity postcondition; AppendConstrainedToken preserves it.
//
//   Post-loop: CloseSpanWithinBudget's postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut), preserving the invariant.
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   Outside-span branch: UnconstrainedStep costs +1 (steps := steps+1) and
//   appends at most 1 token to generated. So both sides grow by at most 1
//   simultaneously, preserving the bound.
//
//   Inside-span branch: SafePenalizedConstrainedStep / AdaptiveConstrainedStep
//   each cost +1 (steps := steps+1). AppendConstrainedToken appends exactly 1
//   token to generated with 0 step cost. So generated grows by at most 1 and
//   steps grows by exactly 1, preserving the bound.
//
//   Post-loop CloseSpanWithinBudget: costs at most remaining = maxSteps - steps,
//   and appends at most remaining tokens to generated. After it, steps := maxSteps,
//   so |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated             := generatedPrefix;
insideConstrainedOut  := insideConstrained;
currentConstrainedOut := currentConstrained;
cost                  := 0;

var guidance := "Solve each math problem step by step using algebra. Express the final answer as a complete Python arithmetic formula in terms of ALL relevant symbolic variables combined with operators (*, **, /, +, -, int()). Place the complete formula inside << >>. Example: <<n0 * (r+1)**d>>. The content inside << >> must never be a single bare variable name like <<n0>>; it must be the full derived expression.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next: Token;
    if |currentConstrainedOut| < 5 {
      // Penalize EOS for the first 5 constrained tokens to prevent
      // single-variable answers; the model is pushed to generate operators
      // and operands that form a complete algebraic expression.
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, [eosToken], 6.0, eosToken
      );
    } else {
      // After 5 tokens, allow EOS normally; model can finish the expression
      // and emit EOS naturally.
      next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    }
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated             := ag;
    insideConstrainedOut  := ai;
    currentConstrainedOut := ac;
  }
}

// If the span is still open (EOS hit inside span or budget used up in free text),
// close it at the longest complete prefix using remaining budget.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated             := cg;
  insideConstrainedOut  := ci;
  currentConstrainedOut := cc;
  steps                 := maxSteps;
}

cost := steps;

